//! Every keyboard layout, held to the TypeScript reference.
//!
//! `fixture-layouts.tsv` is generated by `engine/dump-fixture.mjs --layouts`: the
//! same handful of readings, written in each layout's own key sequences, with the
//! layout named in the first column. The main fixture keeps only two positional
//! ETen cases at its end, which was enough to prove the layout table travelled
//! while there were two tables; with seven, "the table" is most of the content and
//! it deserves a fixture of its own.
//!
//! What this catches: a transcribed key in the wrong row, a component index that
//! disagrees between the two implementations, and a layout that is registered in
//! one language and not the other. The readings are ordinary words, so a failure
//! reads as "ㄋㄧˇ ㄏㄠˇ comes out wrong on 許氏" rather than as a table diff.

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use pingzhu_core::{
    build_syllable_inventory, Dictionary, EngineOptions, InputEngine, Layout,
};

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..")
}

fn engine(layout: Layout) -> InputEngine {
    let lm = repo_root().join("data/bopomofo-lm.tsv");
    let dict = Dictionary::load(&lm).expect("language model");
    let inventory = build_syllable_inventory(&lm).expect("inventory");
    InputEngine::new(dict, inventory, EngineOptions { layout, ..Default::default() })
}

struct Case {
    layout: String,
    keys: String,
    composing: String,
    sentence: String,
    score: f64,
    used_fallback: bool,
    path_words: String,
    page1: String,
}

#[test]
fn every_layout_matches_the_reference() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixture-layouts.tsv");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read {}: {e}\nregenerate with: cd engine && node dump-fixture.mjs --layouts > ../core-rs/tests/fixture-layouts.tsv",
            path.display()
        )
    });

    let cases: Vec<Case> = text
        .lines()
        .filter(|line| !line.is_empty())
        .map(|line| {
            let f: Vec<&str> = line.split('\t').collect();
            assert_eq!(f.len(), 8, "malformed layout fixture row: {line}");
            Case {
                layout: f[0].to_string(),
                keys: f[1].to_string(),
                composing: f[2].to_string(),
                sentence: f[3].to_string(),
                score: f[4].parse().expect("score"),
                used_fallback: f[5] == "1",
                path_words: f[6].to_string(),
                page1: f[7].to_string(),
            }
        })
        .collect();

    assert!(cases.len() > 30, "layout fixture looks truncated: {} cases", cases.len());

    // One engine per layout: creating one reads the 6 MB model, and there is no
    // learning on this path (no candidate is ever chosen), so reuse is safe.
    let mut engines: HashMap<&'static str, InputEngine> = HashMap::new();
    for id in ["standard", "eten", "hsu", "eten26", "ibm", "ginyieh", "mitac"] {
        let layout = Layout::from_id(id).unwrap_or_else(|| panic!("layout {id} is not registered"));
        engines.insert(id, engine(layout));
    }

    let mut covered: HashMap<String, usize> = HashMap::new();
    let mut mismatches: Vec<String> = Vec::new();
    for case in &cases {
        let Some(eng) = engines.get_mut(case.layout.as_str()) else {
            mismatches.push(format!("  unknown layout {:?} in the fixture", case.layout));
            continue;
        };
        eng.reset();
        eng.press_str(&case.keys);
        *covered.entry(case.layout.clone()).or_default() += 1;

        let page1: Vec<String> =
            eng.candidate_page().entries.iter().map(|e| e.word.clone()).collect();
        let page1 = page1.join("|");
        let path_words = eng
            .chosen_path()
            .map(|p| p.nodes.iter().map(|n| n.word.clone()).collect::<Vec<_>>().join("|"))
            .unwrap_or_default();

        let mut problems: Vec<String> = Vec::new();
        if eng.composing() != case.composing {
            problems.push(format!("composing {:?} != {:?}", eng.composing(), case.composing));
        }
        if eng.best_sentence() != case.sentence {
            problems.push(format!("sentence {:?} != {:?}", eng.best_sentence(), case.sentence));
        }
        if (eng.best_score() - case.score).abs() > 1e-6 {
            problems.push(format!("score {} != {}", eng.best_score(), case.score));
        }
        if eng.used_fallback() != case.used_fallback {
            problems.push(format!("usedFallback {} != {}", eng.used_fallback(), case.used_fallback));
        }
        if path_words != case.path_words {
            problems.push(format!("pathWords {path_words:?} != {:?}", case.path_words));
        }
        if page1 != case.page1 {
            problems.push(format!("page1 {page1:?} != {:?}", case.page1));
        }
        if !problems.is_empty() {
            mismatches.push(format!("  {} {:?}: {}", case.layout, case.keys, problems.join("; ")));
        }
    }

    // A layout that silently stopped being exercised would make this test pass by
    // doing nothing, which is the failure mode a table test is most prone to.
    for id in ["standard", "eten", "hsu", "eten26", "ibm", "ginyieh", "mitac"] {
        assert!(
            covered.get(id).copied().unwrap_or(0) > 0,
            "the fixture exercises no case for {id}"
        );
    }

    assert!(
        mismatches.is_empty(),
        "Rust core disagrees with the TypeScript reference on {} case(s):\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
